const CATEGORY_SEEDS = [
  ...geographyCategories,
  ...scienceNatureCategories,
  ...foodDrinkCategories,
] as const satisfies readonly CategorySeed[];

function variants(value: string): readonly string[] {
  return value.split('|').map((item) => item.trim()).filter(Boolean);
}

function buildQuestion(
  categorySetId: string,
  seed: QuestionSeed,
  tierIndex: number,
): AccessibleQuestion {
  const [
    factKey,
    subjectKey,
    clueEn,
    clueEt,
    responseEn,
    responseEt,
    variantsEn,
    variantsEt,
    explanationEn,
    explanationEt,
    sourceTitle,
    sourcePath,
  ] = seed;
  return {
    key: `accessible-corpus:${categorySetId}:${factKey}`,
    tier: (tierIndex + 1) as 1 | 2 | 3 | 4 | 5,
    subjectKey,
    clue: { en: clueEn, et: clueEt },
    response: { en: responseEn, et: responseEt },
    acceptedVariants: { en: variants(variantsEn), et: variants(variantsEt) },
    explanation: { en: explanationEn, et: explanationEt },
    source: {
      sourceId: `wikipedia:${sourcePath.toLocaleLowerCase('en')}`,
      title: sourceTitle,
      url: `https://en.wikipedia.org/wiki/${sourcePath}`,
      license: 'CC-BY-SA-4.0',
      retrievedAt: '2026-08-28',
    },
  };
}

const rawCategories: readonly AccessibleCategory[] = CATEGORY_SEEDS.map((seed) => {
  const target = assignedTargets.find(({ categorySetId }) => categorySetId === seed.categorySetId);
  if (target === undefined) throw new Error(`Missing assigned target ${seed.categorySetId}`);
  const title = ACCESSIBLE_CATEGORY_TITLES.find(
    ({ categorySetId }) => categorySetId === seed.categorySetId,
  );
  if (title === undefined) throw new Error(`Missing approved title ${seed.categorySetId}`);
  return {
    categorySetId: seed.categorySetId,
    batchId: target.batchId,
    name: title.name,
    questions: seed.questions.map((question, index) =>
      buildQuestion(seed.categorySetId, question, index)),
  };
});

export const GEOGRAPHY_SCIENCE_FOOD_CATEGORIES = validateAccessibleCorpus(
  rawCategories,
  assignedTargets,
);
